    "7785": "Se produjo un error durante el proceso de instalación. Al motor de IA le faltan archivos necesarios, lo que hace que se ejecute en modo de compatibilidad. En casos graves, el servicio de IA puede fallar.",
    "7786": "Se recomienda comprobar si el directorio de instalación tiene permisos de escritura. Después de confirmar que no hay ningún problema, reinstale la aplicación, ya no verá este mensaje y el motor de IA a máxima velocidad se reanudará automáticamente.",
