    "7849": "Cambiar",
    "7850": "Después de encenderlo, los modelos locales y en la nube pueden comenzar a pensar, lo que puede mejorar la calidad del análisis de IA, pero aumentará considerablemente el tiempo de respuesta.",
    "7874": "Cola de análisis",
    "7875": "Seleccione la ubicación de almacenamiento del modelo de IA",
    "7876": "El modelo AI es el archivo central que permite que el software tenga capacidades de análisis inteligente y es de gran tamaño.",
    "7877": "Ruta de almacenamiento del modelo",
    "7878": "Consejos amables",
    "7879": "Los diferentes modelos pueden ocupar entre 2 y 8 GB o incluso más espacio. Se recomienda elegir un disco con suficiente espacio restante.",
    "7880": "Priorice la SSD (unidad de estado sólido), que permite una carga de modelos más rápida y un análisis de IA más fluido.",
    "7881": "Simplemente seleccione una carpeta vacía o cree una nueva, no afectará sus archivos existentes.",
    "7883": "Precisión del reconocimiento OCR",
    "7884": "Seleccione el nivel de precisión del reconocimiento de texto OCR. El OCR extremadamente rápido es adecuado para la mayoría de escenarios; El reconocimiento OCR de alta precisión es más preciso pero lleva un poco más de tiempo.",
    "7885": "OCR extremadamente rápido",
    "7887": "OCR de alta precisión",
    "7889": "Reutilizar datos al volver a analizar",
    "7890": "Si el archivo se ha actualizado, desactive este elemento. De lo contrario, si la información básica de algún archivo ya existe, omita esta adquisición de información. La información básica incluye: tipo de archivo, miniatura, metadatos y contenido del archivo.",
    "7891": "Se acelera el análisis y no se volverá a adquirir información de la etapa de clasificación simple.",
    "7892": "Instalación del complemento: LibreOffice",
    "7895": "Ocultar tutorial de instalación de Windows 💡",
    "7896": "Expanda el tutorial de instalación de Windows y configuración de PATH 💡",
    "7897": "Cómo configurar:",
    "7898": "Primero agregue la ruta de instalación de LibreOffice a la variable de entorno PATH del sistema.",
    "7899": "Ubicación predeterminada:",
    "7900": "El modelo está cambiando, por favor espere",
    "7901": "El archivo original se ha perdido o se ha movido en el disco",
    "7902": "Se ha perdido",
